# Search for any year numbers in the data
def find_numbers(obj, depth=0):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            results.extend(find_numbers(v, depth+1))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(find_numbers(item, depth+1))
    elif isinstance(obj, (int, float)):
        if 2020 <= obj <= 2050:
            results.append(obj)
    elif isinstance(obj, str):
        try:
            if any(str(y) in obj for y in range(2020, 2050)):
                results.append(obj[:100])
        except:
            pass
    return results

results = find_numbers(data)
print('Found in JSON:', results[:20])
