# Search through all data files in multiple ways
import os
import re

results = {}

# Try searching for patterns looking for any 2025 budget/surplus/deficit data
for root, dirs, files in os.walk('/app'):
    for f in files:
        fpath = os.path.join(root, f)
        if f.endswith('.txt') or f.endswith('.json'):
            try:
                with open(fpath, 'r', errors='ignore') as file:
                    content = file.read()

                    # Look for 2025 with deficit/surplus patterns
                    patterns = [
                        r'2025.*?(-?\d{1,3}(?:,\d{3})*)\s*(?:million|billion)',
                        r'(-?\d{1,3}(?:,\d{3})*).*?2025.*?(?:surplus|deficit)',
                    ]

                    for p in patterns:
                        matches = re.findall(p, content, re.IGNORECASE)
                        if matches:
                            if fpath not in results:
                                results[fpath] = []
                            results[fpath].extend(matches[:3])
            except Exception as e:
                pass

for f, matches in results.items():
    if matches:
        print(f"\n{f}:")
        for m in set(matches):
            print(f"  {m}")
